import React, { useState } from 'react';
import NavBar from './NavBar';

const professors = [
  {
    id: 1,
    name: 'Prof. Marko Marković',
    image: 'https://via.placeholder.com/100',
    slots: '0/3',
  },
  {
    id: 2,
    name: 'Prof. Ana Anić',
    image: 'https://via.placeholder.com/100',
    slots: '1/3',
  },
  {
    id: 3,
    name: 'Prof. Ivan Ivić',
    image: 'https://via.placeholder.com/100',
    slots: '2/3',
  },
];

const styles = `
.userpage-container {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 32px;
  padding: 10%;
  min-height: 80vh;
  margin-top: 64px;
}
.prof-modal {
  position: relative;
  width: 220px;
  height: 320px;
  background: #fff;
  border-radius: 18px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.12);
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: transform 0.2s, box-shadow 0.2s, width 0.3s, height 0.3s;
  cursor: pointer;
  overflow: hidden;
}
.prof-modal:hover {
  transform: scale(1.07);
  box-shadow: 0 8px 32px rgba(0,0,0,0.18);
}
.prof-modal.expanded {
  width: 340px;
  height: 420px;
  z-index: 10;
  box-shadow: 0 12px 48px rgba(0,0,0,0.22);
  transform: scale(1.12);
}
.prof-image {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  margin-top: 24px;
  object-fit: cover;
  background: #eee;
}
.prof-name {
  margin: 18px 0 0 0;
  font-size: 1.3rem;
  font-weight: 600;
  text-align: center;
}
.prof-slots {
  position: absolute;
  bottom: 18px;
  right: 18px;
  background: #f5f5f5;
  padding: 7px 16px;
  border-radius: 16px;
  font-size: 1rem;
  color: #333;
  font-weight: 500;
  box-shadow: 0 2px 8px rgba(0,0,0,0.07);
}
`;

const UserPage = () => {
  const [expandedId, setExpandedId] = useState(null);

  React.useEffect(() => {
    if (!document.getElementById('userpage-styles')) {
      const style = document.createElement('style');
      style.id = 'userpage-styles';
      style.innerHTML = styles;
      document.head.appendChild(style);
    }
  }, []);

  return (
    <>
      <NavBar />
      <div className="userpage-container">
        {professors.map((prof) => (
          <div
            key={prof.id}
            className={`prof-modal${expandedId === prof.id ? ' expanded' : ''}`}
            onClick={() => setExpandedId(expandedId === prof.id ? null : prof.id)}
          >
            <img src={prof.image} alt={prof.name} className="prof-image" />
            <h2 className="prof-name">{prof.name}</h2>
            <span className="prof-slots">{prof.slots}</span>
          </div>
        ))}
      </div>
    </>
  );
};

export default UserPage;
